class Solution:
    def sortLinkedList(self, head: Optional[ListNode]) -> Optional[ListNode]:
        vals = []
        node = head
        while node:
            vals.append(node.val)
            node = node.next
        vals.sort()
        node = head
        for v in vals:
            node.val = v
            node = node.next
        return head

