class Solution {
public:
    ListNode* sortLinkedList(ListNode* head) {
        vector<int> vals;
        for (ListNode* p = head; p; p = p->next) vals.push_back(p->val);
        sort(vals.begin(), vals.end());
        ListNode* p = head;
        for (int v : vals) {
            p->val = v;
            p = p->next;
        }
        return head;
    }
};

