class Solution:
    def sortLinkedList(self, head: Optional[ListNode]) -> Optional[ListNode]:
        dummy = ListNode(0, head)
        prev, cur = dummy, head
        while cur:
            if cur.val < 0:
                prev.next = cur.next
                cur.next = dummy.next
                dummy.next = cur
                cur = prev.next
            else:
                prev = cur
                cur = cur.next
        return dummy.next

